TP.register({id:"lp4-g5",lp:4,grade:"5",mode:"baseline",nextGrade:"6th grade",build(E){const esc=E.esc;const F=E.F;const PASSAGE="Priya had waited all week for the pond behind the village library to freeze hard enough to skate on. On Friday the ice finally rang like a struck bell when the caretaker tapped it with his pole, and he hung the green flag on the fence. Priya laced her skates with hands that shook like dry leaves. The far end of the pond looked as wide as an ocean. Her little brother Dev pushed off instantly and glided away, easy as a sled on a steep hillside. Priya carefully took one step. Her ankles wobbled. She was not going to fall in front of anybody. A boy she did not recognize skated past and called out, “Bend your knees. The ice is your friend.” Priya bent her knees. The wobbling went quiet. She pushed once, twice, and then she was traveling, the cold air a ribbon against her cheeks. At the farthest fencepost she looked back at the long double line her blades had cut across the whitened pond. Priya did not stop smiling the whole walk home, even when the snowfall started again and filled in her footprints behind her.";const PASSAGE_N=PASSAGE.split(/\s+/).length;const TEXT_A={title:"Built for Deep Snow",body:"Snowshoe hares live in cold northern forests. In summer their fur is brown. As fall turns to winter, new fur grows in white, so a hare is hard to see against snow. Their back feet are very wide and covered with stiff hairs. Those feet spread the hare’s weight so it can run on top of deep snow instead of sinking in, the way a snowshoe does for a person. A hare can also bound more than ten feet in a single jump."};const TEXT_B={title:"When the Snow Comes Late",body:"A snowshoe hare does not decide when to turn white. The change starts when the days get shorter, not when the snow arrives. In many forests, snow now falls later in the year and melts earlier than it did fifty years ago. Scientists who study hares have counted weeks when a white hare sits on bare brown ground, where anything hunting it can spot it easily. Researchers are now looking for forests where some hares stay brown all winter, because those hares may do better as winters get shorter."};const SNOWMAKING="Snow starts high inside a cloud, where the air is colder than a freezer. Up there, tiny specks of dust drift among water droplets. When a droplet freezes onto a speck of dust, a crystal of ice begins to grow. More water vapor sticks to the crystal and freezes, and arms spread out from its six sides. That is why almost every snow crystal has six arms. As the crystal falls, it bumps into other crystals and they clump together, so what lands on a mitten is usually many crystals stuck in one group. The shape depends on the air the crystal passed through. Very cold, dry air makes small, simple crystals. Air closer to freezing with more water in it makes the wide, feathery kind.";const WORDS=["thermometer","disappearance","predictability","uncomfortable","immeasurable","invisibility","observation","electricity","unexpectedly","disagreement","scrimbulation","untrazzable"];function twoTextsHtml(){return`<div class="texts"><article><h3>Text A: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text B: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function lookBack(label,inner){return`<details class="look-back"><summary>Look back at ${label}</summary>${inner}</details>`}function prism(L,W,H,s){s=s||34;const cx=Math.cos(Math.PI/6)*s,cy=Math.sin(Math.PI/6)*s;const ox=W*cx+10,oy=H*s+10;const P=(x,y,z)=>[ox+(x-y)*cx,oy+(x+y)*cy-z*s];const poly=(pts,f)=>`<polygon points="${pts.map(p=>p.map(v=>v.toFixed(1)).join(",")).join(" ")}" fill="${f}" stroke="var(--ink)" stroke-width="1.6"/>`;const cubes=[];for(let x=0;x<L;x++)for(let y=0;y<W;y++)for(let z=0;z<H;z++)cubes.push([x,y,z]);cubes.sort((a,b)=>a[0]+a[1]-(b[0]+b[1])||a[2]-b[2]);let g="";cubes.forEach(([x,y,z])=>{g+=poly([P(x,y,z+1),P(x+1,y,z+1),P(x+1,y+1,z+1),P(x,y+1,z+1)],"var(--gold)");g+=poly([P(x,y+1,z),P(x+1,y+1,z),P(x+1,y+1,z+1),P(x,y+1,z+1)],"var(--sea-soft)");g+=poly([P(x+1,y,z),P(x+1,y+1,z),P(x+1,y+1,z+1),P(x+1,y,z+1)],"var(--sea)")});const w=(L+W)*cx+20,h=(L+W)*cy+H*s+20;return`<svg viewBox="0 0 ${w.toFixed(0)} ${h.toFixed(0)}" width="${Math.min(360,w*1.3).toFixed(0)}" role="img" aria-label="Block of snow built from unit cubes">${g}</svg>`}function grid(){const u=42,o=40,n=8;let s=`<svg viewBox="0 -16 ${o+n*u+46} ${o+n*u+56}" width="420" role="img" aria-label="Coordinate grid of the pond park with points P, Q, and R">`;const X=v=>o+v*u,Y=v=>o+(n-v)*u;for(let i=0;i<=n;i++){s+=`<line x1="${X(i)}" y1="${Y(0)}" x2="${X(i)}" y2="${Y(n)}" stroke="var(--line)" stroke-width="1.5"/><line x1="${X(0)}" y1="${Y(i)}" x2="${X(n)}" y2="${Y(i)}" stroke="var(--line)" stroke-width="1.5"/>`;s+=`<text x="${X(i)}" y="${Y(0)+24}" text-anchor="middle" font-size="18" fill="var(--ink)">${i}</text>`;if(i)s+=`<text x="${X(0)-14}" y="${Y(i)}" text-anchor="end" dominant-baseline="central" font-size="18" fill="var(--ink)">${i}</text>`}s+=`<line x1="${X(0)}" y1="${Y(0)}" x2="${X(n)+20}" y2="${Y(0)}" stroke="var(--ink)" stroke-width="3"/><line x1="${X(0)}" y1="${Y(0)}" x2="${X(0)}" y2="${Y(n)-20}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<text x="${X(n)+26}" y="${Y(0)+6}" font-size="20" font-weight="700" fill="var(--ink)">x</text><text x="${X(0)-6}" y="${Y(n)-28}" font-size="20" font-weight="700" fill="var(--ink)">y</text>`;[["P",4,7],["Q",7,3],["R",5,0]].forEach(([l,x,y])=>{s+=`<circle cx="${X(x)}" cy="${Y(y)}" r="9" fill="var(--coral)"/><text x="${X(x)+12}" y="${Y(y)-12}" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">${l}</text>`});return s+"</svg>"}function grid4(){const u=34,o=30,n=5;let s=`<svg viewBox="0 -14 ${2*o+2*n*u} ${2*o+2*n*u+14}" width="400" role="img" aria-label="Coordinate grid with four quadrants and points M and N">`;const X=v=>o+(v+n)*u,Y=v=>o+(n-v)*u;for(let i=-n;i<=n;i++){s+=`<line x1="${X(i)}" y1="${Y(-n)}" x2="${X(i)}" y2="${Y(n)}" stroke="var(--line)" stroke-width="1.5"/><line x1="${X(-n)}" y1="${Y(i)}" x2="${X(n)}" y2="${Y(i)}" stroke="var(--line)" stroke-width="1.5"/>`;if(i){s+=`<text x="${X(i)}" y="${Y(0)+18}" text-anchor="middle" font-size="14" fill="var(--ink)">${i<0?"−"+-i:i}</text><text x="${X(0)-8}" y="${Y(i)}" text-anchor="end" dominant-baseline="central" font-size="14" fill="var(--ink)">${i<0?"−"+-i:i}</text>`}}s+=`<line x1="${X(-n)-12}" y1="${Y(0)}" x2="${X(n)+12}" y2="${Y(0)}" stroke="var(--ink)" stroke-width="3"/><line x1="${X(0)}" y1="${Y(-n)+12}" x2="${X(0)}" y2="${Y(n)-12}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<text x="${X(n)+16}" y="${Y(0)+6}" font-size="18" font-weight="700" fill="var(--ink)">x</text><text x="${X(0)-5}" y="${Y(n)-16}" font-size="18" font-weight="700" fill="var(--ink)">y</text>`;[["M",-4,1],["N",3,-2]].forEach(([l,x,y])=>{s+=`<circle cx="${X(x)}" cy="${Y(y)}" r="8" fill="var(--coral)"/><text x="${X(x)+11}" y="${Y(y)-10}" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">${l}</text>`});return s+"</svg>"}function toolOn(k){const d=document.getElementById("toolDock");return!!(d&&!d.hidden&&d.querySelector(`[data-tpk="${k}"]`))}function syncTools(){paintWords();paintPsg()}function watchDock(){const d=document.getElementById("toolDock");if(!d||d._tpWatch)return;d._tpWatch=true;new MutationObserver(syncTools).observe(d,{childList:true,attributes:true,attributeFilter:["hidden"]})}function tagNote(n,k,line){n.gen=n.gen||{};const old=n.gen[k]||"";let t=n.text||"";if(old&&t.includes(old))t=t.replace(old,()=>line);else if(line)t=(t.trim()?t.replace(/\s+$/,"")+"\n":"")+line;n.text=t.replace(/^\s+/,"").replace(/\n{3,}/g,"\n\n");n.gen[k]=line;E.save();const ft=document.getElementById("fText");if(ft)ft.value=n.text}let wordIdx=0;function wordsInner(on){const w=WORDS[wordIdx];return`<p style="text-align:center;margin:0">Word ${wordIdx+1} of ${WORDS.length}</p><p class="huge" style="font-size:${on?"clamp(2rem,4.6vw,4rem)":"clamp(2.6rem,9vw,6.5rem)"}">${on?SPLITS[w]:w}</p>
  <div class="row center"><button class="btn ghost" id="wPrev" ${wordIdx===0?"disabled":""}>Back</button><button class="btn ghost" id="wNext" ${wordIdx===WORDS.length-1?"disabled":""}>Next</button></div>`}function paintWords(){const box=document.getElementById("tpWords");if(!box)return;box.innerHTML=wordsInner(toolOn("chunk"));box.querySelector("#wPrev").onclick=()=>{wordIdx=Math.max(0,wordIdx-1);paintWords()};box.querySelector("#wNext").onclick=()=>{wordIdx=Math.min(WORDS.length-1,wordIdx+1);paintWords()}}const SENTS=PASSAGE.split(/(?<=[.!?]”?)\s+(?=[A-Z“])/);let rulerIdx=0,tStart=0,tInt=null;function psgInner(on){return on?SENTS.map((x,i)=>`<span class="${i===rulerIdx?"cur":""}">${x}</span>`).join(" "):PASSAGE}function paintPsg(){const el=document.getElementById("psg");if(!el)return;const on=toolOn("ruler");if(!on)rulerIdx=0;el.classList.toggle("ruler",on);el.innerHTML=psgInner(on)}const ORF5=[[183,"at or above the 90th percentile"],[160,"between the 75th and 90th percentiles"],[133,"between the 50th and 75th percentiles"],[109,"between the 25th and 50th percentiles"],[84,"between the 10th and 25th percentiles"]];function orfBand(w){for(const[cut,t]of ORF5)if(w>=cut)return t;return"below the 10th percentile"}function wordsRight(n,pi){const r=n.p&&n.p[pi]?n.p[pi].right:"";return r!==""&&r!==void 0&&r!==null&&!isNaN(+r)?Math.max(0,Math.min(PASSAGE_N,+r)):null}function wcpm(n,pi){if(!n.secs)return null;const r=wordsRight(n,pi);return Math.round((r===null?PASSAGE_N:r)*60/n.secs)}function orfText(n,pi){const w=wcpm(n,pi);if(w===null)return"";const r=wordsRight(n,pi);return`Timed read: ${n.secs} seconds, ${w} WCPM (one unpracticed read; ${r===null?"figured with no missed words, so type the words read correctly above to update it":r+" of "+PASSAGE_N+" words correct"}${(n.sup||[]).includes("ruler")?"; read with the reading ruler":""}). Compared against the same table the LP 1 game used, Hasbrouck and Tindal 2017, but the winter column because LP 4 is the midyear game: grade 5 winter norms are 50th percentile 133, 25th 109, 10th 84. This score is ${orfBand(w)}. For reference, the winter 50th percentile is 120 WCPM in grade 4 and 97 in grade 3. LP 1 scored this student against the fall column (50th percentile 121), so expect the midyear bar to be higher.`}function readHtml(n){return`<p class="passage" id="psg">${PASSAGE}</p>
  <div class="row no-key" style="margin-top:16px;padding-top:10px;border-top:2px dashed var(--line)"><span class="small">Teacher timer</span><button class="chip" id="tGo">Start</button><button class="chip" id="tStop">Stop</button><button class="chip" id="tReset">Reset</button><strong id="tShow">${n&&n.secs?n.secs+" sec":"0 sec"}</strong></div>`}function bindRead(root,ctx){const n=ctx.note,pi=ctx.stop.parts.indexOf(ctx.part),show=root.querySelector("#tShow");const upd=()=>tagNote(n,"orf",orfText(n,pi));clearInterval(tInt);tStart=0;root.querySelector("#tGo").onclick=()=>{tStart=Date.now();clearInterval(tInt);show.textContent="0 sec";tInt=setInterval(()=>{if(!show.isConnected){clearInterval(tInt);tStart=0;return}show.textContent=Math.round((Date.now()-tStart)/1e3)+" sec"},250)};root.querySelector("#tStop").onclick=()=>{if(!tStart)return;clearInterval(tInt);n.secs=Math.max(1,Math.round((Date.now()-tStart)/1e3));tStart=0;show.textContent=n.secs+" sec";upd()};root.querySelector("#tReset").onclick=()=>{clearInterval(tInt);tStart=0;delete n.secs;show.textContent="0 sec";upd()};const inp=document.querySelector(`#stopView [data-f="right"][data-pi="${pi}"]`);if(inp)inp.addEventListener("input",()=>{if(n.secs)upd()});paintPsg();watchDock()}const METHODS=["Typed, spellcheck on","Typed, spellcheck off","Voice typing / dictation software","Handwritten","Dictated to teacher or parent (scribed)"];function writeStats(t){const w=(t.trim().match(/\S+/g)||[]).length,s=(t.match(/[^.!?]+[.!?]+/g)||[]).length;return`${w} words, about ${s} sentences`}function boxHtml(n,label){const w=n&&n.w||{};return`<div class="no-key" style="margin-top:16px"><label class="small" style="display:block">${label}<textarea class="wbox" data-wbox>${esc(w.text||"")}</textarea></label>
  <p class="small wstats" data-wstats>${w.text&&w.text.trim()?writeStats(w.text):""}</p>
  <label class="small" style="display:block;margin:6px 0 0">How the student produced the writing <select data-wmethod style="font:inherit;padding:4px 8px;border:2px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink)"><option value="">Choose</option>${METHODS.map(m=>`<option${w.method===m?" selected":""}>${m}</option>`).join("")}</select></label></div>`}function bindBox(root,ctx,what){const n=ctx.note,ta=root.querySelector("[data-wbox]"),sel=root.querySelector("[data-wmethod]"),st=root.querySelector("[data-wstats]");const upd=()=>{n.w=n.w||{};n.w.text=ta.value;n.w.method=sel.value;const has=!!ta.value.trim();st.textContent=has?writeStats(ta.value):"";tagNote(n,"w",has?`${what}. Produced by: ${sel.value||"(not recorded)"}. Length: ${writeStats(ta.value)}. """${ta.value.trim()}"""`:"")};ta.oninput=upd;sel.onchange=upd}const WDIR="Type it, use voice typing, or write on paper. Send it to your teacher or hold it up when you finish.";const STOPS=[{id:1,title:"Mitten Words",short:"Words",parts:[{std:["RF.5.3"],dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading long words with prefixes, suffixes, and roots",kind:"words",n:12,dur:60,render:()=>{wordIdx=0;return`<div id="tpWords">${wordsInner(false)}</div>`},bind:()=>{paintWords();watchDock()},printHtml:()=>`<p><em>Words shown one at a time:</em> ${WORDS.join(", ")}</p>`,key:["Read each word. scrimbulation and untrazzable are made-up words: listen for how the student splits syllables and uses prefixes and suffixes (scrim-bu-la-tion, un-traz-za-ble).","Watch for: prefixes and suffixes (dis-, un-, in-, im-, pre-, -ment, -ance, -able, -ly, -tion, -ity), roots (therm, vis, dict, electr, measure, observe), and whether the student breaks long words into chunks or guesses from the first letters."]}]},{id:2,title:"Read by the Cabin",short:"Read",parts:[{std:["RF.5.4"],dir:"Read the story out loud at your normal speed.",desc:`a ${PASSAGE_N}-word grade-level story read aloud`,kind:"read",n:PASSAGE_N,label:"words read correctly",dur:90,render:ctx=>readHtml(ctx.note),bind:(root,ctx)=>bindRead(root,ctx),printHtml:()=>`<p class="passage">${PASSAGE}</p>`,key:[`${PASSAGE_N} words. Mark errors and self-corrections on the passage in the record sheet. Then type the number of words read correctly in Teacher notes.`,"Use the teacher timer under the passage: click Start when the student reads the first word and Stop at the last word. It figures words correct per minute (WCPM), compares it to the grade 5 winter (midyear) norms from the same Hasbrouck and Tindal 2017 table the LP 1 game used, and adds that line to the Notes box for this stop.","Note pace, phrasing, and expression (does the student’s voice change for the line the boy calls out?) in your notes.","For a clean fluency baseline, time the first read without the reading ruler. If the student needs the ruler, the WCPM line says it was read with support."]}]},{id:3,title:"Pond Story Questions",short:"Story Qs",parts:[{title:"Quote It",std:["RL.5.1"],dir:"Answer out loud. Read the exact words from the story.",desc:"quoting the story to tell what it says and to back up inferences",dur:75,html:()=>`<p class="passage sm">${PASSAGE}</p>`,qs:["Read me the exact words that show Priya was nervous before she skated.","How did Priya feel at the end? Read me the words that helped you figure that out.","Why do you think the caretaker hung the green flag on the fence? Read me the words that back up your answer."],key:["Reads an exact line: “laced her skates with hands that shook like dry leaves” or “Her ankles wobbled.” (RL.5.1, explicit)","Happy, proud, or pleased with herself. Quotes “Priya did not stop smiling the whole walk home.” (RL.5.1, inference)","The green flag means the ice was finally thick enough to skate on. Quotes “the ice finally rang like a struck bell when the caretaker tapped it with his pole” or “freeze hard enough to skate on.” (RL.5.1, inference)"]},{title:"Word Pictures",std:["RL.5.4"],dir:"Answer out loud. Open the story again if you need it.",desc:"explaining similes and metaphors in a story",dur:45,html:()=>lookBack("the skating story",`<p class="passage sm">${PASSAGE}</p>`),qs:["What does “hands that shook like dry leaves” mean?","“The cold air a ribbon against her cheeks.” Is that a simile or a metaphor? What does it tell you about the air?","The far end of the pond “looked as wide as an ocean.” What does that tell you about how Priya saw it?"],key:["She was so nervous her hands were trembling. (RL.5.4, simile)","Metaphor, because it says the air IS a ribbon with no like or as. It tells you the cold air felt like a smooth cool band brushing her face. (RL.5.4)","It looked much too far away to reach, even though a pond is not really ocean sized. (RL.5.4)"]}]},{id:4,title:"Snowfall Place Value",short:"Place Value",parts:[{std:["5.NBT.A.1"],dir:"Look at the two measurements. Answer out loud.",desc:"comparing the value of a digit in two places (10 times as much and 1/10)",dur:50,html:()=>`<p class="big">The village weather station writes down how many inches of snow fell. Here are two of its numbers.</p>`,fig:()=>`<p class="huge" style="font-size:clamp(2.6rem,6.5vw,5.2rem)">4.444 &nbsp; 66.6</p>`,qs:["In 4.444, how does the 4 in the hundredths place compare to the 4 in the tenths place?","In 4.444, how does the 4 in the ones place compare to the 4 in the tenths place?","In 66.6, how does the 6 in the tens place compare to the 6 in the ones place?"],key:["It is 1/10 as much (0.04 is 1/10 of 0.4). Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)","It is 10 times as much (4 is 10 times 0.4). Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)","It is 10 times as much (60 is 10 times 6). Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)"]}]},{id:5,title:"Snow Gauge Decimals",short:"Decimals",parts:[{std:["5.NBT.A.3"],dir:"Say number 1 out loud. Write the rest on your paper and hold it up.",desc:"reading, writing, and comparing decimals to thousandths",dur:75,html:()=>`<p class="big">A snow gauge is a tube that catches snow so you can measure it. These are gauge readings in inches.</p>`,qs:["Read this number out loud: 7.205","Write 3.816 in expanded form.","Write this as a number: nine and seventeen thousandths.","Which is greater: 0.73 or 0.709? Use &gt; or &lt;."],key:["Seven and two hundred five thousandths. Partial: seven point two zero five is approaching, since the place value name is what is asked. (5.NBT.A.3)","3 × 1 + 8 × (1/10) + 1 × (1/100) + 6 × (1/1000), or 3 + 0.8 + 0.01 + 0.006. Partial: three of the four places written is approaching. (5.NBT.A.3)","9.017. Partial: 9.17 puts the digits in the wrong places and does not count. (5.NBT.A.3)","0.73 &gt; 0.709 (5.NBT.A.3). The longer decimal is the smaller one, so the student has to line up the place values instead of counting digits. Or: compare 730 thousandths against 709 thousandths. Partial: the right choice with the sign the wrong way round is approaching."]}]},{id:6,title:"Icicle Brackets",short:"Brackets",parts:[{std:["5.OA.A.1"],dir:"Solve each one on your paper. Tell your teacher your answers.",desc:"evaluating expressions with parentheses, brackets, and braces",dur:80,qs:["3 × (7 + 5) = ?","30 − [4 × (3 + 2)] = ?","{6 + [12 ÷ (1 + 3)]} × 4 = ?","Add parentheses to make this true: 24 − 4 × 5 = 100"],key:["36. Partial: 26 comes from multiplying before adding and does not count. (5.OA.A.1)","10. Partial: stopping at 4 × 5 = 20 without the subtraction is approaching. (5.OA.A.1)","36. Partial: 9 found by stopping inside the braces is approaching. (5.OA.A.1)","(24 − 4) × 5 = 100, so the parentheses go around the subtraction. Partial: parentheses placed anywhere that does not give 100 does not count. (5.OA.A.1)"]}]},{id:7,title:"Hot Cocoa Fractions",short:"Fractions",parts:[{title:"Add and Subtract",std:["5.NF.A.1"],dir:"Solve on your paper. Show your work and hold it up.",desc:"adding and subtracting fractions and mixed numbers with unlike denominators",dur:105,qs:["1/3 + 2/5 = ?","7/8 − 1/3 = ?","1 1/3 + 2 1/6 = ?"],key:["11/15. Or: thirtieths work too, 10/30 + 12/30 = 22/30 = 11/15. Partial: 3/8 comes from adding across and does not count. (5.NF.A.1)","13/24. Partial: 6/5 comes from subtracting across and does not count. (5.NF.A.1)","3 1/2. Or: change to sixths first, 8/6 + 13/6 = 21/6 = 3 1/2. Partial: 3 2/9 comes from adding across and does not count. (5.NF.A.1)"]},{title:"Fraction Word Problems",std:["5.NF.A.2"],dir:"Solve the first problem on your paper. Explain the second one out loud.",desc:"a fraction addition word problem and a benchmark fraction check",dur:75,qs:["Lena shoveled snow for 5/6 of an hour before lunch and 3/4 of an hour after lunch. How long did she shovel in all?","Omar says 7/8 − 1/2 = 6/6. Without solving, how can you tell he is wrong?"],key:["19/12 of an hour, or 1 7/12 hours, from 5/6 + 3/4 = 10/12 + 9/12. Shows a model or equation and renames the improper fraction as a mixed number. Or: twenty-fourths work too, 20/24 + 18/24 = 38/24. Partial: 19/12 right with no mixed number given is approaching. (5.NF.A.2)","6/6 equals 1 whole. He took something away from 7/8, so the answer has to be less than 7/8, and 7/8 is already less than 1. Partial: saying he is wrong with no benchmark used is approaching. (5.NF.A.2, benchmark fractions)"]}]},{id:8,title:"Share at the Cabin",short:"Share It",parts:[{title:"Fractions as Division",std:["5.NF.B.3"],dir:"Solve on your paper. Tell your teacher your answers.",desc:"division word problems with fraction and mixed number answers",dur:60,qs:["5 loaves of bread are shared equally by 8 people at the cabin. How much bread does each person get?","A 14 pound bag of birdseed is split equally into 4 feeders. How many pounds go in each feeder? Between what two whole numbers is your answer?"],key:["5/8 of a loaf. Or: 5 ÷ 8 written as a division counts equally. Partial: 8/5 reverses the share and does not count. (5.NF.B.3)","3 1/2 pounds, between 3 and 4. Partial: 3 1/2 right with no pair of whole numbers named is approaching. (5.NF.B.3)"]},{title:"Multiply Fractions",std:["5.NF.B.4"],dir:"Solve on your paper. Tell your teacher your answers.",desc:"multiplying fractions and whole numbers by fractions",dur:60,qs:["3/4 × 8 = ?","2/3 × 3/8 = ?","What is 1/3 of 2/5?"],key:["6. Or: 8 ÷ 4 = 2, then 2 × 3 = 6. (5.NF.B.4)","6/24, simplified to 1/4. Or: cancel the 3s first, which leaves 2/8 = 1/4. (5.NF.B.4)","2/15. Or: a 3 by 5 area model with 2 of the 15 squares shaded. (5.NF.B.4)"]}]},{id:9,title:"Snow Block Builder",short:"Volume",parts:[{title:"What Is Volume?",std:["5.MD.C.3"],dir:"Look at the block. Answer out loud.",desc:"counting unit cubes for volume and telling what volume measures",dur:40,html:()=>`<p class="big">Packed snow can be cut into blocks and stacked like bricks. This stack is made of cubes.</p>`,fig:()=>`<div class="figure">${prism(4,2,3)}</div>`,qs:["Each cube is 1 cubic unit. What is the volume of this stack? Say the units.","Why do we measure volume in cubic units instead of flat squares?"],key:["24 cubic units. Partial: 24 with no unit named is approaching. (5.MD.C.3)","Because the cubes fill the solid in three directions, long, wide, and tall, with no gaps, so the unit has to be a cube. Flat squares only cover a surface. Partial: naming the three directions with nothing said about flat squares covering only a surface is approaching. (5.MD.C.3)"]},{title:"Find the Volume",std:["5.MD.C.5"],dir:"Solve on your paper. Tell your teacher your answers.",desc:"finding volume by multiplying and by adding the volumes of two boxes",dur:75,fig:()=>`<div class="figure">${prism(4,2,3)}</div>`,qs:["The stack in the picture is 4 cubes long, 2 cubes wide, and 3 cubes tall. Show how to find its volume using multiplication.","A mold for packing snow is 6 inches long, 4 inches wide, and 2 inches tall. What is its volume?","A wall is built from two block stacks: one is 3 by 3 by 2, and the other is 5 by 1 by 2. What is the total volume?"],key:["4 × 2 × 3 = 24, or base 8 × height 3 = 24 cubic units. Partial: the right total with no multiplication shown is approaching. (5.MD.C.5)","48 cubic inches. Or: 6 × 4 = 24 for the base, then 24 × 2. Partial: 48 with no unit named is approaching. (5.MD.C.5)","18 + 10 = 28 cubic units. Partial: one of the two stacks worked out is approaching. (5.MD.C.5, volume is additive)"]}]},{id:10,title:"Pond Park Map",short:"Grid",parts:[{std:["5.G.A.1"],dir:"Look at the map grid. Answer out loud.",desc:"naming the origin, the axes, and the coordinates of points on a grid",dur:60,html:()=>`<p class="big">This grid is a map of the park around the frozen pond. P is the warming hut, Q is the sledding hill, and R is the front gate. One unit is one step.</p>`,fig:()=>`<div class="figure">${grid()}</div>`,qs:["Find the spot where the two axes cross. What is that point called, and what are its coordinates?","What are the coordinates of the warming hut, point P?","Which place is at (7, 3)?","In the ordered pair for the sledding hill, which number tells you how far across? which tells you how far up? How do you know which is which?","The gate, point R, is at (5, 0). Why is the second number 0?"],key:["The origin, at (0, 0), where the x-axis and the y-axis cross. Partial: naming the origin with no coordinates given is approaching. (5.G.A.1)","(4, 7). Partial: (7, 4) reverses the pair and is approaching. (5.G.A.1)","Q, the sledding hill. Partial: naming the place at (3, 7) instead reads the pair in the wrong order and is approaching. (5.G.A.1)","The first number, 7, tells how far across along the x-axis, and the second, 3, tells how far up the y-axis. The order is fixed, the x-coordinate always comes first. Partial: the two numbers matched up with nothing said about the order being fixed is approaching. (5.G.A.1)","It sits right on the x-axis, so you do not move up at all. Partial: naming the x-axis with nothing said about not moving up is approaching. (5.G.A.1)"]}]},{id:11,title:"Shovel the Grammar",short:"Grammar",parts:[{std:["L.5.1"],dir:"Say each sentence out loud the correct way. For the last one, say the words you find.",desc:"spoken grammar items (verb tenses, either/or, parts of speech)",dur:75,qs:["Fix it: “Yesterday we shovel the steps and cleared the path.”","Finish it: “By the time the bus came, the snow ____ (stop).”","Finish it: “By March, the pond ____ (melt) all the way.”","Use either/or: “Tomas could drive the plow. Nadia could drive the plow.” Only one of them will.","“Whew, the sled flew down the hill and across the field!” Find the interjection, a preposition, and the conjunction."],key:["shoveled (L.5.1, fixing a tense shift)","had stopped (L.5.1, past perfect)","will have melted (L.5.1, future perfect)","Either Tomas or Nadia will drive the plow. (L.5.1, correlative conjunctions)","Whew; down or across; and (L.5.1)"]}]},{id:12,title:"Two Winter Texts",short:"Two Texts",parts:[{title:"Quote the Text",std:["RI.5.1"],dir:"Read both texts to yourself. Then answer out loud with the exact words from the text.",desc:"quoting an informational text to tell what it says and to back up an inference",dur:100,html:()=>twoTextsHtml(),qs:["Read me the sentence from Text A that tells why a hare can run on top of deep snow instead of sinking in.","Why is a late snowfall a problem for a snowshoe hare? Read me the words from Text B that back up your answer."],key:["Reads the sentence: “Those feet spread the hare’s weight so it can run on top of deep snow instead of sinking in, the way a snowshoe does for a person.” (RI.5.1, explicit)","The hare turns white on a daylight schedule, so if the snow is late it is white on brown ground and easy to spot. Quotes “The change starts when the days get shorter, not when the snow arrives” or the sentence about a white hare on bare brown ground. (RI.5.1, inference)"]},{title:"Quick Notes",std:["W.5.8"],dir:"Write your notes on paper or type them. Hold them up or send them to your teacher.",desc:"notes in the student’s own words from two texts with a list of sources",n:3,label:"checks met",dur:90,html:()=>lookBack("Text A and Text B",twoTextsHtml())+`<p class="big" style="font-size:1.5rem">Jot 3 short notes about snowshoe hares in your own words. Words and phrases are fine, no full sentences. Put A or B after each note. Then write the two titles at the bottom as your sources.</p>`,render:ctx=>boxHtml(ctx.note,"Notes and sources (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student notes"),key:["3 notes with the key facts from the texts (W.5.8)","Notes are in the student’s own words, not copied word for word (W.5.8)","Labels A or B and writes both titles as a list of sources (W.5.8)"]},{title:"Put It Together",std:["RI.5.9"],dir:"Answer out loud. Use ideas from both texts.",desc:"putting together information from two texts on the same topic",dur:110,qs:["Using both texts, tell me what helps a snowshoe hare get through winter? what is making that harder now.","Text A says the white fur makes a hare hard to see against snow. Text B says the change to white starts when the days get shorter, not when the snow arrives. Put those two facts together. Why is snow that comes late a problem for the hare?","Text B says researchers are looking for forests where some hares stay brown all winter. Using what Text A told you about the hare's feet, answer this. Say one thing a brown hare would still have going for it in deep snow."],html:()=>lookBack("Text A and Text B",twoTextsHtml()),key:["Combines both texts out loud: white winter fur that hides it on snow and wide hairy back feet that let it run on deep snow (A), plus the problem that the color change follows daylight, not snow, so a white hare can end up on bare brown ground when snow comes late or melts early (B). Needs at least one idea from each text. (RI.5.9)","The fur turns white on a daylight schedule (B), so when the snow is late the hare is already white and sits on bare brown ground, where the hiding that Text A describes does the opposite and makes it easy for anything hunting it to spot. Needs the camouflage from A and the daylight trigger from B. Partial: saying only that the hare is easy to see, with nothing about daylight, is approaching. (RI.5.9)","Text A says the wide back feet covered with stiff hairs spread the hare's weight so it can run on top of deep snow instead of sinking in, and that it can bound more than ten feet. Those feet work whatever color the fur is, so a brown hare keeps the speed and the footing on snow and loses only the hiding. Needs the feet from A applied to B's brown hares. (RI.5.9)"]}]},{id:13,title:"Listen by the Fire",short:"Listen",parts:[{std:["SL.5.2"],dir:"Listen while your teacher reads. Then sum it up out loud in your own words.",desc:"summarizing a text read aloud",n:4,label:"checks met",dur:95,html:()=>`<p class="huge" aria-hidden="true">${F.icon("snowflake",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about how a snow crystal is made up in a cloud. Then sum it up in a few sentences.</p>`,read:SNOWMAKING,key:["Gives the main idea: snow crystals form in clouds when water freezes onto specks of dust and keeps growing (SL.5.2)","Includes 2 or more key details: ice grows out from six sides so crystals have six arms; falling crystals clump together; the temperature and how damp the air is decide the shape (SL.5.2)","Keeps the order and uses the student’s own words (SL.5.2)","Keeps it short, no extra opinions or small details (SL.5.2)"]}]},{id:14,title:"Mitten Opinion Talk",short:"Opinion",parts:[{std:["SL.5.4"],dir:"Pick one question. Plan for 1 minute. Then tell your opinion and your reasons out loud.",desc:"presenting an opinion out loud with reasons and details",n:6,label:"checks met",dur:90,html:()=>`<p class="big">Pick one and tell me what you think. Take 1 minute to plan.</p><ul class="qlist" style="margin-top:14px"><li>Should kids have a say in what time the school day starts?</li><li>On a cold, stormy day, is it better to go outside or stay inside?</li></ul><div class="row center" style="margin-top:20px;gap:14px"><span class="pill" style="font-size:1.2rem">My opinion</span><span class="pill" style="font-size:1.2rem">Reason 1</span><span class="pill" style="font-size:1.2rem">Reason 2</span><span class="pill" style="font-size:1.2rem">So...</span></div>`,key:["States a clear opinion (SL.5.4)","Gives reasons in a logical order (SL.5.4)","Backs reasons with facts or examples (SL.5.4)","Uses transition words like for example, also, therefore, consequently (SL.5.4)","Ends with a concluding statement (SL.5.4)","Speaks clearly at an understandable pace (SL.5.4)"]}]},{id:15,title:"Writer’s Choice",short:"Write",parts:[{alt:{group:"write",label:"Opinion",icon:"💬",hint:"Write the opinion you just told me"},std:["W.5.1","L.5.1"],dir:WDIR,desc:"an opinion writing piece",n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write down the opinion you just told me. 4 or 5 sentences. You can type it or say it with voice typing.</p><ul class="qlist" style="margin-top:14px"><li>Say your opinion</li><li>Give 2 reasons with an example</li><li>Use a linking word</li><li>End with a closing sentence</li></ul>`,render:ctx=>boxHtml(ctx.note,"Opinion writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Introduces the topic and states an opinion (W.5.1)","Reasons are in a logical order (W.5.1)","Reasons are supported with facts or details (W.5.1)","Links opinion and reasons with words like for example, specifically, consequently (W.5.1)","Has a concluding sentence (W.5.1)","Verb tenses stay consistent and correct (L.5.1)"]},{alt:{group:"write",label:"Explain It",icon:"❄️",hint:"Teach about snow crystals or snowshoe hares"},std:["W.5.2"],dir:WDIR,desc:"an informative writing piece",n:6,label:"checks met",dur:300,html:()=>`<p class="big">Pick one. Explain it to someone who has never seen snow. Use what you read or heard today. 5 to 7 sentences. Type it or use voice typing.</p><ul class="qlist" style="margin-top:14px"><li>${F.icon("snowflake",26)} How a snow crystal is made in a cloud</li><li>${F.icon("rabbit",26)} What helps a snowshoe hare get through winter</li></ul>`,render:ctx=>boxHtml(ctx.note,"Informative writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Introduces the topic clearly (a title or heading counts as formatting) (W.5.2)","Groups related facts together in a logical order (W.5.2)","Develops the topic with facts, definitions, or details (W.5.2)","Links ideas with words like also, for example, in contrast, especially (W.5.2)","Uses topic words correctly (crystal, water vapor, freeze, six arms or snowshoe hare, fur, daylight, sink in) (W.5.2)","Ends with a concluding sentence (W.5.2)"]},{alt:{group:"write",label:"Tell a Story",icon:"📖",hint:"A time the weather changed your plans"},std:["W.5.3"],dir:WDIR,desc:"a narrative writing piece",n:6,label:"checks met",dur:300,html:()=>`<p class="big">Write about a time the weather changed your plans. It can be real or made up. 5 to 8 sentences. Type it or use voice typing.</p><div class="row center" style="margin-top:20px;gap:14px"><span class="pill" style="font-size:1.2rem">Beginning</span><span class="pill" style="font-size:1.2rem">Middle</span><span class="pill" style="font-size:1.2rem">End</span></div>`,render:ctx=>boxHtml(ctx.note,"Narrative writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Sets up the situation and introduces the narrator or characters (W.5.3)","Events unfold in a clear order (W.5.3)","Uses dialogue or description to show how characters feel or react (W.5.3)","Uses transition words to show time (first, later, after that, finally) (W.5.3)","Uses concrete or sensory details (what the writer saw, heard, felt) (W.5.3)","Ends with a conclusion that follows from the events (W.5.3)"]}]},{id:16,title:"Hidden in the Slush",short:"Tiny Bits",parts:[{std:["5-PS1-1"],n:3,dur:75,dir:"Answer out loud.",desc:"using a model of particles too small to be seen to explain what happens to matter",html:()=>`<p class="big">A village crew spreads road salt on the lane. An hour later the ice is gone and so is the salt, but a dog that licks the puddle pulls a face.</p>
     <div class="figure">${F.icon("snowflake",80)}${F.icon("drop",80)}${F.icon("boot",80)}</div>`,qs:["The salt cannot be seen in the puddle. Is it gone? What is the evidence?","Use the idea of particles too small to see to explain where the salt went.","In the cold you can see your breath, and then it vanishes. What happened to that water, and is it still matter?"],key:["It is not gone. The puddle tastes salty, which shows the salt is still there, and the puddle weighs the water plus the salt. (5-PS1-1)","The salt broke into particles far too small to see and spread out among the water particles, so it is mixed all through the puddle rather than sitting in one visible pile. (5-PS1-1)","The water in warm breath cooled and formed tiny droplets you could see, then warmed again and spread out as water vapor, which is particles too small to see. It is still matter and still water. (5-PS1-1)"]},{std:["5-PS1-3"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"identifying materials from measured properties rather than from appearance",html:()=>`<p class="big">Four white or near-white materials came out of unlabelled tubs in the village shed. Nobody tasted anything. Here is what the tests showed.</p>
     <table class="bigTable"><tr><th>Tub</th><th>Melts ice it is sprinkled on?</th><th>Dissolves in water?</th><th>Fizzes with vinegar?</th><th>Feels gritty between the fingers?</th></tr>
     <tr><td>E</td><td>yes</td><td>yes</td><td>no</td><td>yes</td></tr>
     <tr><td>G</td><td>no</td><td>no</td><td>no</td><td>yes</td></tr>
     <tr><td>H</td><td>no</td><td>yes</td><td>yes</td><td>no</td></tr>
     <tr><td>J</td><td>no</td><td>no</td><td>yes</td><td>yes</td></tr></table>
     <p class="big">The four materials are road salt, washed sand, baking soda, and crushed limestone.</p>`,qs:["Which tub is the road salt, and which result is the giveaway?","Two tubs fizz with vinegar. Which is the baking soda, and which test separates it from the other?","Tub G passed none of the first three tests. Which material is it, and what does that tell you about using a test that nothing passes?"],key:["E. It is the only one that melts ice, which is what road salt is for. (5-PS1-3)","H is the baking soda, because it dissolves in water while the crushed limestone, J, does not. (5-PS1-3)","G is the washed sand. A test nothing else passes is still useful, because failing every other test narrows the answer down to one material. (5-PS1-3)"]}]},{id:17,title:"Sealed in the Cold",short:"Weigh In",parts:[{std:["5-PS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"using measurements to show that total weight is conserved through heating, cooling, and mixing",html:()=>`<p class="big">Three sealed jars were weighed outdoors, carried inside overnight, and weighed again.</p>
     <table class="bigTable"><tr><th>Sealed jar</th><th>What was inside at night</th><th>Weight outdoors</th><th>Weight next morning</th></tr>
     <tr><td>1</td><td>a scoop of packed snow</td><td>480 g</td><td>?</td></tr>
     <tr><td>2</td><td>water with road salt stirred in</td><td>520 g</td><td>?</td></tr>
     <tr><td>3</td><td>water that froze solid and then thawed</td><td>365 g</td><td>365 g</td></tr></table>`,qs:["Jar 1 now holds a small pool of water that fills much less of the jar. What does it weigh?","Jar 2 looks like plain water now. What does it weigh, and why?","Jar 3 froze and thawed and weighs the same both times. What does that show about freezing and melting?"],key:["480 g. The snow melted into less space but no matter left the sealed jar, so the weight is unchanged. Taking up less room is not the same as weighing less. (5-PS1-2)","520 g. The salt dissolved and spread out among the water particles. Nothing left the jar, so the total weight is the same. (5-PS1-2)","They rearrange the particles between solid and liquid without adding or removing any, so the total weight of matter is conserved through cooling and heating alike. (5-PS1-2)"]},{std:["5-PS1-4"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"deciding from evidence whether mixing two substances made a new substance",html:()=>`<p class="big">Three winter mixings, with what was observed.</p>
     <table class="bigTable"><tr><th>Mixing</th><th>What was seen</th></tr>
     <tr><td>a hand warmer opened and shaken in air</td><td>the gray powder inside turned rust brown and the packet grew hot for an hour</td></tr>
     <tr><td>road salt stirred into snow</td><td>the snow melted and the mix got colder, and boiling the water away left the salt behind</td></tr>
     <tr><td>a fizzing tablet dropped into cold water</td><td>bubbles streamed off for a minute, then the tablet was gone and the water was clear</td></tr></table>`,qs:["Which two mixings made a new substance? Give the evidence for each.","Which one is only a mixture, and what is the evidence?","The salt mix got colder and the hand warmer got hotter. Does a temperature change on its own prove a new substance formed? Use the chart to answer."],key:["The hand warmer, because the powder changed color permanently and gave off heat, and the fizzing tablet, because a gas streamed off and the tablet was used up. (5-PS1-4)","The road salt and snow. Boiling the water away gave the salt back, so the starting materials were only mixed. (5-PS1-4)","No. Both mixings changed temperature, but only one made a new substance. Temperature is a useful clue, and you need other evidence too, such as a gas forming, a color change that cannot be undone, or being unable to get the starting materials back. (5-PS1-4)"]}]},{id:18,title:"What Builds a Spruce",short:"Plant Food",parts:[{std:["5-LS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing from measurements that plants get their material for growth from air and water",html:()=>`<p class="big">A spruce seedling was planted in a sealed planter of weighed soil beside the village hall and given only water and daylight for fifteen years.</p>
     <div class="figure">${F.icon("sprout",76)}${F.icon("pine",88)}${F.icon("snowCloud",76)}</div>
     <table class="bigTable"><tr><th></th><th>At planting</th><th>Fifteen years later</th></tr>
     <tr><td>the tree, dried</td><td>1 kg</td><td>190 kg</td></tr>
     <tr><td>dry soil in the planter</td><td>900 kg</td><td>889 kg</td></tr></table>`,qs:["How much dry weight did the tree gain, and how much did the soil lose?","Where did nearly all the new wood and needle material come from?","The tree kept growing through winters when the ground was frozen solid. What does that suggest about where the material comes from?"],key:["The tree gained 189 kg. The soil lost 11 kg. (5-LS1-1)","From air and water. Carbon dioxide from the air and water taken up by the roots are built into the tree using energy from sunlight. (5-LS1-1)","If the growth depended on digging material out of the soil, frozen ground would stop it. The material comes mainly from the air and from water, and the plant stores what it makes and uses it when conditions allow. (5-LS1-1)"]},{std:["5-PS3-1"],n:3,dur:70,dir:"Look at the chain. Answer out loud.",desc:"using a model to trace the energy in an animal's food back to the sun",html:()=>`<p class="big">One path energy takes in the village.</p>
     <p class="huge" style="font-size:2.2rem;margin:10px 0;text-align:center">${F.icon("sun",46)} &rarr; ${F.icon("wheat",46)} &rarr; ${F.icon("cow",46)} &rarr; ${F.icon("milk",46)}</p>
     <p class="big">Hay cut in summer is fed to the cows all winter, and the village drinks the milk.</p>`,qs:["It is January and there is no grass growing. Where did the energy in today's milk come from?","Explain why cutting and storing hay is really a way of storing something else.","Someone says the cow makes the energy in the milk. What is wrong with that?"],key:["From last summer's sunlight. The hay captured and stored it, the cow ate the hay, and some of that energy is in the milk. (5-PS3-1)","It is a way of storing energy that came from sunlight. The hay holds the energy the grass captured in summer so it can be used months later. (5-PS3-1)","The cow cannot make energy. It only passes along energy that was already stored in its food, and the food got it from sunlight. The cow uses up most of it for its own living and warmth. (5-PS3-1)"]}]},{id:19,title:"Under the Snow",short:"Matter Cycle",parts:[{std:["5-LS2-1"],n:4,dur:90,dir:"Look at the model. Answer out loud.",desc:"describing with a model how matter moves among plants, animals, decomposers, and the environment",html:()=>`<p class="big">Under a deep snow cover the ground stays near freezing rather than bitterly cold, and a thin layer of air sits between the snow and the leaf litter. Life carries on there all winter.</p>
     <table class="bigTable"><tr><th>From</th><th>To</th><th>How</th></tr>
     <tr><td>air and soil</td><td>grasses and shrubs</td><td>they take in carbon dioxide, water, and minerals in the growing season</td></tr>
     <tr><td>grasses and shrubs</td><td>voles and rabbits</td><td>they feed on stems and bark under the snow</td></tr>
     <tr><td>dead leaves, stems, and animal waste</td><td>fungi and bacteria in the litter</td><td>slow breakdown, because it is cold</td></tr>
     <tr><td>fungi and bacteria</td><td>air and soil</td><td>minerals and gases released</td></tr></table>
     <div class="figure">${F.icon("leaf",70)}${F.icon("rabbit",70)}${F.icon("mushroom",70)}${F.icon("snowflake",70)}</div>`,qs:["Why does the breakdown in the third row happen so slowly in winter?","A thick leaf litter is still there in spring but much of it is gone by late summer. Where did it go?","Snow is cleared off a village lawn all winter so the ground freezes hard. Predict what that does to the cycle in this model.","Trace one mineral from a dead leaf into a new spring shoot."],key:["Decomposers work more slowly in the cold. Their activity depends on temperature, so near freezing they break material down at a fraction of the summer rate. (5-LS2-1)","Decomposers broke it down once the soil warmed, releasing gases into the air and minerals into the soil. (5-LS2-1)","The decomposers in that patch are slowed almost to a stop and some are killed, so dead material builds up and fewer minerals are returned to the soil for spring growth. (5-LS2-1)","Fungi and bacteria break down the leaf and release the mineral into the soil water, a root takes it up, and it ends up built into the new shoot. (5-LS2-1)"]}]},{id:20,title:"Icicles and Sleds",short:"Down",parts:[{std:["5-PS2-1"],n:3,dur:70,dir:"Answer out loud.",desc:"arguing that the gravitational force Earth exerts on objects is directed down",html:()=>`<p class="big">Icicles hang in a row under the village hall roof. A sled waits at the top of the slope.</p>
     <div class="figure">${F.icon("igloo",80)}${F.icon("sled",84)}${F.icon("snowflake",72)}</div>`,qs:["Icicles always point the same way no matter which side of the roof they hang from. Which way, and why?","A sled let go on the slope moves along the hill, not straight down. Does that mean the pull is sideways? Explain.","Two children argue. One says Earth pulls things toward the ground. The other says toward the center of Earth. Which wording works everywhere on the planet, and why?"],key:["Straight down. Water running off the roof is pulled straight down by Earth as it freezes, so every icicle grows in the same direction whatever the roof is doing. (5-PS2-1)","No. The pull is still straight down. The hillside is in the way and pushes back, so the only movement left is along the slope. Over a cliff edge it would fall straight down. (5-PS2-1)","Toward the center of Earth. Down toward the ground means a different direction in space at each place on the globe, and all of those directions point toward Earth's center. (5-PS2-1)"]},{std:["5-ESS2-1"],n:3,dur:75,dir:"Read the story. Answer out loud.",desc:"describing with an example how the geosphere, biosphere, hydrosphere, and atmosphere interact",html:()=>`<p class="big">The Earth system has four parts. The geosphere is rock and soil. The biosphere is living things. The hydrosphere is all the water. The atmosphere is air.</p>
     <p class="big">A mild afternoon melts snow on the village lane. Water runs into cracks in the road. That night the air drops below freezing, the water in the cracks freezes and expands, and by spring the lane is full of potholes. Meltwater that soaked into the meadow instead feeds the stream for weeks, and willow roots take up what they need.</p>
     <div class="figure">${F.icon("thermometer",72)}${F.icon("drop",72)}${F.icon("mountain",72)}${F.icon("tree",72)}</div>`,qs:["Name the two spheres interacting when water freezes inside a crack and breaks the road apart.","Meltwater soaks into the meadow and feeds the stream for weeks. Which spheres does that connect?","Pick the one interaction in the story that involves living things and describe it."],key:["The hydrosphere and the geosphere. Water in the rock and road material expands as it freezes and breaks it up, which is how weathering works. The atmosphere is in it too, since the air temperature drove the freezing. (5-ESS2-1)","The hydrosphere and the geosphere, because water moves into and through the soil and comes out slowly into the stream. The atmosphere is where the snow came from. (5-ESS2-1)","Willow roots take up the meltwater. That is biosphere drawing on hydrosphere, and the roots also hold the soil of the geosphere in place. (5-ESS2-1)"]}]},{id:21,title:"Winter Sky",short:"Sky",parts:[{std:["5-ESS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing that the sun looks brightest because of how near it is, not because it gives off the most light",html:()=>`<p class="big">Three stars visible from the village on a clear winter night, with how much light each really gives off.</p>
     <table class="bigTable"><tr><th>Star</th><th>Light it gives off</th><th>Distance from Earth</th></tr>
     <tr><td>the sun</td><td>1 unit</td><td>8 light-minutes</td></tr>
     <tr><td>Sirius</td><td>about 25 units</td><td>8.6 light-years</td></tr>
     <tr><td>Capella</td><td>about 80 units</td><td>43 light-years</td></tr></table>
     <div class="figure">${F.icon("sun",76)}${F.icon("star",76)}${F.icon("snowCloud",76)}</div>`,qs:["Sirius and Capella are both brighter than the sun in the light they give off. Why does neither one light the village lane?","Capella gives off about three times the light of Sirius but looks fainter in the sky. Explain using the distance column.","A villager says the sun must be the most powerful star in the sky because it is the brightest. Correct that statement."],key:["They are light-years away while the sun is 8 light-minutes away. Light spreads out as it travels, so almost none of theirs reaches the lane. (5-ESS1-1)","Capella is 43 light-years away and Sirius is 8.6, about five times nearer. That difference in distance outweighs Capella giving off more light. (5-ESS1-1)","The sun looks brightest only because it is by far the nearest star. Both Sirius and Capella give off much more light, and plenty of stars give off thousands of times more. (5-ESS1-1)"]},{std:["5-ESS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"finding patterns in graphed data about shadows, day length, and the night sky",html:()=>`<p class="big">A pole beside the village hall is 2 m tall. Its noon shadow was measured on the twenty-first of four months.</p>
     <table class="bigTable"><tr><th>Date</th><th>Noon shadow</th><th>Hours of daylight</th></tr>
     <tr><td>21 December</td><td>4.4 m</td><td>9.2</td></tr>
     <tr><td>21 March</td><td>2.0 m</td><td>12.1</td></tr>
     <tr><td>21 June</td><td>0.8 m</td><td>15.0</td></tr>
     <tr><td>21 September</td><td>2.0 m</td><td>12.2</td></tr></table>`,qs:["Two dates have the same shadow length and almost the same daylight. Which two, and why would that be?","Describe the pattern: what happens to the noon shadow as the hours of daylight go up?","The winter stars over the village are not the same as the summer stars. What causes that yearly change?"],key:["21 March and 21 September. They sit halfway between the shortest and longest days, so the midday sun is at about the same height on both and the shadow matches. (5-ESS1-2)","The noon shadow gets shorter as the daylight gets longer. Longest shadow with the shortest day in December, shortest shadow with the longest day in June. (5-ESS1-2)","Earth travels around the sun during the year, so the night side faces a different part of space in winter than in summer and different stars are overhead. (5-ESS1-2)"]}]},{id:22,title:"Frozen Water",short:"Water",parts:[{std:["5-ESS2-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"describing the amounts and percentages of water and fresh water in Earth's reservoirs",html:()=>`<p class="big">Where Earth's water sits, and how much of it is locked up as ice.</p>
     <table class="bigTable"><tr><th>Reservoir</th><th>Share of all water</th><th>Salty or fresh?</th></tr>
     <tr><td>oceans</td><td>about 97%</td><td>salty</td></tr>
     <tr><td>ice caps and glaciers</td><td>about 2%</td><td>fresh, frozen</td></tr>
     <tr><td>groundwater</td><td>about 1%</td><td>mostly fresh</td></tr>
     <tr><td>lakes, rivers, snow on the ground, soil, air</td><td>far less than 1%</td><td>mostly fresh</td></tr></table>`,qs:["What percentage of all Earth's water is fresh? What percentage of all Earth's water is fresh and also liquid?","Snow on the village fields is in the last row, not the second. Why does the chart separate snow from ice caps?","Describe what a bar graph of this chart would look like. Then say which bars a reader would struggle to see."],key:["About 3% is fresh. Of that, about 1% of all water is liquid fresh water, mostly groundwater, since the 2% in ice caps is frozen. (5-ESS2-2)","Seasonal snow melts within months and returns to streams and soil, while ice caps and glaciers hold water for thousands of years. They are different reservoirs because the water stays for very different lengths of time. (5-ESS2-2)","One bar nearly the full height for the oceans and three tiny bars beside it. The ice, groundwater, and surface water bars would all be hard to see, and the last one almost invisible. (5-ESS2-2)"]},{std:["5-ESS3-1"],n:3,dur:75,dir:"Read the two reports. Answer out loud.",desc:"combining information about ways communities use science to protect resources and the environment",html:()=>`<p class="big">Two villages looked for better ways to get through winter.</p>
     <table class="bigTable"><tr><th>Village</th><th>What they did</th><th>Result after one winter</th></tr>
     <tr><td>Birch Hollow</td><td>switched from spreading salt everywhere to spreading grit on side lanes and salt only on the steep hill</td><td>salt use down 60%, and the stream below the village tested far less salty in spring</td></tr>
     <tr><td>Pine Row</td><td>paid for loft insulation and door seals on every home in the village</td><td>fuel burned for heating down by a third, and warmer houses</td></tr></table>`,qs:["Why would less road salt matter to a stream below the village?","Pine Row burned a third less fuel without anyone turning the heating down. Explain how that works.","Combine the two reports into advice for a third village with a salty stream and high fuel bills."],key:["Salt washes off the roads into the stream with the meltwater. Too much salt harms the plants and animals that live in fresh water, so using less salt keeps the stream healthier. (5-ESS3-1)","Insulation and seals slow the escape of heat, so the heat already produced stays inside longer and less fuel is needed to hold the same temperature. (5-ESS3-1)","Do both: grit on the gentler lanes with salt only where it is really needed, and insulation and door seals to cut fuel use. The answer has to draw on each report. (5-ESS3-1)"]}]},{id:23,title:"Design a Draft Stopper",short:"Design It",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Listen, then answer out loud.",desc:"defining a design problem with criteria for success and constraints",read:"Cold air pours under the village hall door every time the wind gets up, and the room nearest the entry is too cold to use for meetings. The caretaker wants something that blocks the draft but still lets the door open and shut easily, because the door is used dozens of times a day. It must be made from fabric and filling already in the hall store, and it must not be fixed to the door, because the hall is rented and nothing may be screwed to it.",qs:["Say the problem in one sentence.","Name two things the finished design must do to count as a success.","Name two limits the caretaker has to work inside."],key:["Cold air comes under the hall door and makes the nearest room too cold to use, so the hall needs the gap blocked. (3-5-ETS1-1)","Any two criteria from the story: blocks the draft under the door, and still lets the door open and shut easily dozens of times a day. (3-5-ETS1-1)","Any two constraints: only fabric and filling already in the hall store, and nothing may be screwed or fixed to the door. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"comparing possible solutions against the criteria and constraints",html:()=>`<p class="big">Three ideas, each tested for a week with the same thermometer in the cold room.</p>
     <table class="bigTable"><tr><th>Idea</th><th>Room temperature gained</th><th>Door still easy to use?</th><th>Materials in store?</th><th>Fixed to the door?</th></tr>
     <tr><td>K: a loose stuffed tube laid against the gap</td><td>2.5 degrees</td><td>yes, but it needs nudging back</td><td>yes</td><td>no</td></tr>
     <tr><td>L: a stuffed tube sewn to a sleeve that slides over the bottom of the door</td><td>3.5 degrees</td><td>yes, moves with the door</td><td>yes</td><td>no, it slides on</td></tr>
     <tr><td>M: a brush strip screwed along the bottom of the door</td><td>4.0 degrees</td><td>yes</td><td>no</td><td>yes</td></tr></table>`,qs:["Which idea gained the most warmth? Explain why it is still not the right choice here.","Compare K and L. Which better meets the criteria, and what makes the difference?","Which idea would you recommend, and name every criterion and limit it satisfies."],key:["M gained 4.0 degrees, but it has to be screwed to the door and uses materials that are not in the store, so it breaks both limits. (3-5-ETS1-2)","L. It gains more warmth and it moves with the door, so nobody has to nudge it back into place after every use. (3-5-ETS1-2)","L. It blocks the draft, gaining 3.5 degrees, the door still opens and shuts easily, it uses fabric and filling from the store, and it slides on rather than being fixed to the door. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Read the test plan. Answer out loud.",desc:"planning a fair test with controlled variables and naming the failure points to improve",html:()=>`<p class="big">The caretaker tested two fillings for the tube, measuring the temperature in the cold room each time.</p>
     <table class="bigTable"><tr><th></th><th>Test 1</th><th>Test 2</th></tr>
     <tr><td>filling</td><td>loose wool scraps</td><td>rolled foam offcuts</td></tr>
     <tr><td>tube length</td><td>90 cm</td><td>90 cm</td></tr>
     <tr><td>outside temperature during the test</td><td>minus 3 degrees</td><td>minus 3 degrees</td></tr>
     <tr><td>temperature gained in the room</td><td>2.1 degrees</td><td>3.4 degrees</td></tr>
     <tr><td>what went wrong</td><td>the wool squashed flat and left a gap at one end</td><td>the foam tube was too stiff and the door scraped it</td></tr></table>`,qs:["What was held the same, and what was changed? Why is that a fair test?","The caretaker nearly ran test 2 on a milder day. Explain why that would have spoiled the comparison.","Name a change that would fix the failure in each test."],key:["The tube length and the outside temperature were held the same and only the filling changed, so the difference in warmth gained can be traced to the filling. (3-5-ETS1-3)","The outside temperature would have been different as well as the filling, so a better result might have come from the milder weather rather than the foam. Two changes at once make the result impossible to read. (3-5-ETS1-3)","Test 1 squashed and left a gap, so use more filling, pack it in sections so it cannot slide, or choose a springier filling. Test 2 scraped, so make the tube slimmer, soften the foam, or raise the sleeve a few millimeters. Any fix tied to the stated failure counts. (3-5-ETS1-3)"]}]},{id:24,title:"How Nations Governed Themselves",short:"Councils",parts:[{std:["HSS-5.1"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing how pre-Columbian nations organized decisions, families, and shared work",html:()=>`<p class="big">American Indian nations before 1492 had their own governments. They were not all the same.</p>
     <table class="bigTable"><tr><th>Nation or region</th><th>How decisions were made</th></tr>
     <tr><td>the Haudenosaunee, also called the Iroquois, in the eastern woodlands</td><td>five nations joined in a confederacy with a Great Council; leaders were chosen by clan mothers and could be removed by them</td></tr>
     <tr><td>Pueblo villages of the desert Southwest</td><td>each village ran its own affairs through councils of respected members, with duties shared out among families</td></tr>
     <tr><td>nations of the Great Plains</td><td>bands made their own decisions; several bands met in larger gatherings at certain times of year</td></tr>
     <tr><td>nations of the Pacific Northwest coast</td><td>leading families held rights to fishing places and passed them on, and held feasts where goods were given away</td></tr></table>`,qs:["The Haudenosaunee joined five nations under one Great Council. What is the advantage of several nations agreeing to act together?","Clan mothers chose leaders and could remove them. Compare that with how a king got his position in Europe at the same time.","On the Great Plains, bands decided for themselves most of the year. Why would that suit the way those nations lived?","Pick any two rows and name one way the two systems were different."],key:["They stop fighting each other, can settle disputes by talking, and are far stronger facing an outside threat, because an attack on one brings the others. Partial: one advantage named is approaching. (HSS-5.1)","A king inherited the position for life and could not usually be removed. A Haudenosaunee leader was chosen by clan mothers for his conduct and could be removed if he failed the people, so power came from the community rather than from birth. Partial: one of the two systems described is approaching. (HSS-5.1)","Bands moved separately following the buffalo across a huge area, so the people on the spot had to be able to decide quickly. Gathering everyone for every decision would have been impossible. Partial: naming the moving bands with nothing said about deciding quickly is approaching. (HSS-5.1)","Any supported pair. For example the Haudenosaunee had one council for five nations while Pueblo villages each decided alone, or Northwest leadership passed down through families while Haudenosaunee leaders were chosen and could be removed. Partial: two rows named with no difference between them is approaching. (HSS-5.1)"]}]},{id:25,title:"Hunting for a Passage",short:"Passage",parts:[{std:["HSS-5.2"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"tracing the search for a northern sea route and the explorations it produced",html:()=>`<p class="big">Spain controlled the southern sea route to Asia, so England, France, and the Netherlands spent a century hunting for a way through or around the north. They called it the Northwest Passage.</p>
     <table class="bigTable"><tr><th>Voyage</th><th>How far they got</th><th>What they found instead</th></tr>
     <tr><td>John Cabot, 1497</td><td>the coast of Newfoundland</td><td>enormous cod fishing grounds</td></tr>
     <tr><td>Jacques Cartier, 1534 and 1535</td><td>up the Saint Lawrence River to rapids</td><td>a route deep inland and trade with nations along it</td></tr>
     <tr><td>Henry Hudson, 1609</td><td>up a river in what is now New York until it turned shallow</td><td>a fur trading region claimed by the Netherlands</td></tr>
     <tr><td>Henry Hudson, 1610</td><td>into the great bay now named after him</td><td>a frozen dead end</td></tr></table>
     <div class="figure">${F.icon("compass",76)}${F.icon("snowflake",76)}${F.icon("sailboat",76)}</div>`,qs:["What were all four voyages looking for, and why did these countries want it so badly?","None of them found the passage. Name two valuable things they found instead.","Cartier stopped at rapids and Hudson stopped where the river turned shallow. Why would that end a search for a sea route?","A passage really does exist across the top of North America, through the Arctic. Why was it useless to a ship in the 1600s?"],key:["A sea route west or north to Asia. Spain and Portugal controlled the known routes, so a northern passage would have let the others trade for Asian goods without permission or a fight. Partial: naming the route with no account of why these countries wanted it is approaching. (HSS-5.2)","Any two: the cod fishing grounds off Newfoundland, the fur trade, a route far inland along the Saint Lawrence, and land their countries then claimed. Partial: one valuable thing named is approaching. (HSS-5.2)","A trading ship needs deep water all the way through. Rapids and shallows mean no sea route for a cargo ship, however far a small boat might get. Partial: saying the river stopped them with nothing said about a cargo ship needing deep water is approaching. (HSS-5.2)","It is choked with sea ice for most of the year and the wooden ships of the time could be crushed or frozen in. It was far too dangerous and slow to carry cargo. Partial: naming the ice with nothing said about the ships of the time is approaching. (HSS-5.2)"]},{std:["HSS-5.3"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining how alliances between American Indian nations and European powers worked and what they cost",html:()=>`<p class="big">When European powers went to war in North America, American Indian nations had to decide what to do. Their choices were their own, made for their own reasons.</p>
     <table class="bigTable"><tr><th>During the war between Britain and France, 1754 to 1763</th></tr>
     <tr><td>France had fewer settlers and traded mainly for furs, so French claims pressed less on American Indian land</td></tr>
     <tr><td>Britain had far more settlers, who cleared and fenced land as they moved inland</td></tr>
     <tr><td>many nations allied with France; the Haudenosaunee mostly sided with Britain or stayed out</td></tr>
     <tr><td>Britain won, France gave up its claims, and British settlers pushed west in far greater numbers</td></tr></table>`,qs:["Why would many nations prefer the French as neighbors to the British?","What did a nation gain by making an alliance during the war?","Britain won the war. Explain why that outcome was bad news for nations that had allied with either side.","This is cooperation and conflict at the same time. Explain how both words fit the chart."],key:["France sent far fewer settlers and wanted furs rather than farmland, so French presence took much less land. British settlers cleared and fenced ground as they came, which took the land nations depended on. Partial: naming the furs with nothing said about British settlement taking land is approaching. (HSS-5.3)","Trade goods, weapons, support against rival nations, and a promise of protection or of limits on settlement. Partial: one gain named is approaching. (HSS-5.3)","With France gone there was no longer a rival power to balance against, so nations lost their bargaining position, and British settlement moved west in far greater numbers whichever side a nation had chosen. Partial: saying Britain took over with nothing said about losing the rival to balance against is approaching. (HSS-5.3)","Nations and Europeans cooperated through trade and military alliance while at the same time coming into conflict over land and broken agreements. The same relationship held both at once. Partial: one of the two words explained is approaching. (HSS-5.3)"]}]},{id:26,title:"Colonial Days and New Ideas",short:"Colonies",parts:[{std:["HSS-5.4"],n:4,dur:165,dir:"Read the chart. Answer out loud.",desc:"describing daily life and the social institutions of the colonial era",html:()=>`<p class="big">A child's day in the colonies depended on where the family lived, what the family did, and whether the child was free.</p>
     <table class="bigTable"><tr><th>Who</th><th>A typical day</th></tr>
     <tr><td>a farm child in New England</td><td>chores before light, a few winter months at a small town school the Puritan town had set up so that children could read for themselves, fieldwork and animals the rest of the year</td></tr>
     <tr><td>a Quaker child in Pennsylvania</td><td>taught at a school run by the local Quaker meeting, which took girls as well as boys, and in a few places admitted free Black children</td></tr>
     <tr><td>an apprentice in a town</td><td>lived in a master's house from about twelve, worked and learned a trade for seven years, then could work on their own</td></tr>
     <tr><td>a plantation owner's child in the South</td><td>taught at home by a hired tutor, sometimes sent to England for schooling</td></tr>
     <tr><td>an enslaved child on a plantation</td><td>put to work young, no schooling, and in many colonies it was against the law to teach them to read</td></tr></table>`,qs:["What was an apprenticeship, and what did the apprentice get out of it?","Two rows name schools set up by religious groups. According to the chart, who set up each one? why did New England children often go to school only in winter?","In many colonies it was against the law to teach an enslaved child to read. What does a law like that tell you about what the people who wrote it were afraid of?","Pick two rows and name the biggest difference between those two children's chances in life."],key:["A young person lived and worked in a skilled worker's household for a set number of years, learning the trade in exchange for the labor, and came out able to earn a living at it. Partial: describing the arrangement with nothing said about what the apprentice came out with is approaching. (HSS-5.4)","The New England town school was set up by the Puritan town so children could read for themselves, and the Pennsylvania school was run by the local Quaker meeting, which took girls as well as boys. On the winter term: there was no fieldwork to do in winter, and in the growing season children were needed on the farm, so school fitted into the months when the land was idle. Both halves are needed for full credit. Partial: one half without the other is approaching, so both schools matched with nothing on the winter term sits there. (HSS-5.4)","That reading gives a person information, the ability to write a pass or a letter, and access to ideas and to others in the same situation. Keeping people from reading was a way of keeping them controlled. Partial: saying they wanted to keep people down with no account of what reading would give them is approaching. (HSS-5.4)","Any supported pair. For example the apprentice could end up with a trade and his own business, while the enslaved child had no schooling and no way out at all, since enslavement was for life and passed to children. Partial: two rows named with no difference in their chances is approaching. (HSS-5.4)"]},{std:["HSS-5.5"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining how ideas about rights and self-government became a cause of the Revolution",html:()=>`<p class="big">Taxes and soldiers were not the only causes. Ideas spread too, in pamphlets that sold by the thousand.</p>
     <table class="bigTable"><tr><th>Idea</th><th>What it claimed</th></tr>
     <tr><td>natural rights</td><td>people are born with rights no government gave them and no government may take away</td></tr>
     <tr><td>consent of the governed</td><td>a government is only legitimate if the people it rules agree to it</td></tr>
     <tr><td>Common Sense, a pamphlet by Thomas Paine, 1776</td><td>argued in plain language that an island should not rule a continent and that the colonies should be independent</td></tr>
     <tr><td>rights as Englishmen</td><td>colonists claimed they already held the rights of any subject in England, including trial by a local jury and no tax without representation</td></tr></table>`,qs:["What is a natural right, and how is it different from a right a government hands out?","Common Sense sold in enormous numbers. Why would a plainly written pamphlet matter more than a careful legal argument?","Colonists claimed rights as Englishmen, then later claimed rights as people. Why was that shift important?","Pick one idea from the chart and explain how it could turn a complaint about taxes into a reason to leave the empire."],key:["A natural right belongs to a person simply for being a person, so no government can grant it or remove it. A right handed out by a government can be changed or taken back by that same government. Partial: defining a natural right with no contrast to one a government grants is approaching. (HSS-5.5)","Plain language reached ordinary people who were not lawyers, so the argument spread through taverns, shops, and farms and changed what large numbers of people thought was possible. Partial: saying it was easier to read with nothing said about how far it spread is approaching. (HSS-5.5)","Claiming rights as Englishmen only asked Britain to treat them properly within the empire. Claiming rights as people meant the rights did not depend on Britain at all, which allowed them to argue for a country of their own. Partial: one of the two claims explained is approaching. (HSS-5.5)","Any supported answer. For example consent of the governed turns the tax question into a question about whether Parliament has any right to rule them, and if it does not, then independence follows rather than a better tax. Partial: an idea named with no step from the tax complaint to leaving the empire is approaching. (HSS-5.5)"]},{std:["HSS-5.6"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing the part foreign powers and volunteers played in the course of the war",html:()=>`<p class="big">The war was not fought by the thirteen states alone.</p>
     <table class="bigTable"><tr><th>Who</th><th>What they contributed</th></tr>
     <tr><td>France, from 1778</td><td>money, supplies, an army, and a fleet; the fleet at Yorktown cut off escape by sea</td></tr>
     <tr><td>Spain, from 1779</td><td>fought Britain in the south and along the Gulf coast, and supplied money and goods</td></tr>
     <tr><td>the Marquis de Lafayette of France</td><td>served as a general in the Continental Army from the age of nineteen</td></tr>
     <tr><td>Friedrich von Steuben of Prussia</td><td>wrote the drill manual and trained the army at Valley Forge</td></tr></table>`,qs:["Name two different kinds of help France gave.","Why would a French fleet matter at Yorktown, which was a land siege?","Why would France and Spain help a rebellion against a king when they had kings of their own?","Would the war have turned out the same without foreign help? Give a reason from the chart."],key:["Any two: money, supplies, soldiers, a navy, and officers who trained and led troops. Partial: one kind of help named is approaching. (HSS-5.6)","The British army at Yorktown was trapped against the coast. With a French fleet offshore it could not be supplied by sea and could not be evacuated, so surrender became the only option. Partial: saying the fleet helped with nothing said about supply or escape by sea is approaching. (HSS-5.6)","Not out of agreement with the ideas. Britain was their rival, and weakening Britain and taking back territory and trade served their own interests. Partial: saying they liked the colonists is not yet right; naming the rivalry with no interest of their own named is approaching. (HSS-5.6)","Any supported answer. The chart makes it hard to say yes, since the fleet at Yorktown decided that siege and the Valley Forge training reshaped the army, but a student may also argue the Americans could have outlasted Britain anyway. The reason matters more than the verdict. Partial: a verdict with no reason from the chart is approaching. (HSS-5.6)"]}]},{id:27,title:"Arguing Over the Constitution",short:"New Nation",parts:[{std:["HSS-5.7"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing the ratification debate over the Constitution and how it was settled",html:()=>`<p class="big">Writing the Constitution in 1787 was only half the job. Nine of the thirteen states had to agree to it, and the argument was fierce.</p>
     <table class="bigTable"><tr><th></th><th>Federalists</th><th>Anti-Federalists</th></tr>
     <tr><td>main claim</td><td>the country needs a national government strong enough to tax, defend, and settle disputes</td><td>a strong national government far away will swallow the states and threaten liberty</td></tr>
     <tr><td>who spoke for them</td><td>James Madison, Alexander Hamilton, John Jay, in essays known as the Federalist Papers</td><td>Patrick Henry, George Mason, and others writing in newspapers</td></tr>
     <tr><td>biggest worry</td><td>that the states would drift apart and the country would fail</td><td>that there was no written list of rights in the document</td></tr></table>
     <p class="big">The states ratified after supporters promised that a list of rights would be added. Those became the first ten amendments.</p>`,qs:["Name the main argument on each side.","What were the Federalist Papers, and what were they for?","The Anti-Federalists lost the vote. Name the thing they won anyway, and say why it matters today.","Both sides said they were protecting liberty. Explain how two groups could say that and still disagree completely."],key:["Federalists argued the country needed a national government strong enough to tax, defend, and settle disputes. Anti-Federalists argued a distant strong government would overwhelm the states and endanger liberty. Partial: one side's argument given is approaching. (HSS-5.7)","A series of essays by Madison, Hamilton, and Jay explaining and defending the Constitution, written to persuade states, especially New York, to ratify it. Partial: naming the essays with no account of what they were for is approaching. (HSS-5.7)","The Bill of Rights, the first ten amendments, added because they insisted on it. Those are the written protections for speech, assembly, a fair trial, and more that people still rely on. Partial: naming the Bill of Rights with nothing said about why it matters today is approaching. (HSS-5.7)","They disagreed about where the danger came from. One side thought liberty was most at risk from a government too weak to keep order and hold the country together, the other from a government too strong and too far away to be watched. Partial: one side's fear named is approaching. (HSS-5.7)"]},{std:["HSS-5.8"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining why people left Europe and what drew them to the United States before 1860",html:()=>`<p class="big">Between 1789 and the 1850s millions of people arrived. Historians sort their reasons into pushes, which drove people out, and pulls, which drew them in.</p>
     <table class="bigTable"><tr><th>Pushes</th><th>Pulls</th></tr>
     <tr><td>a potato disease destroyed the main food crop in Ireland through the late 1840s and more than a million people died</td><td>farmland for sale cheaply, far cheaper than anything in Europe</td></tr>
     <tr><td>failed uprisings and hard times in the German states around 1848</td><td>work digging canals, laying railroad track, and in mills and factories</td></tr>
     <tr><td>little land to inherit and few paid jobs at home</td><td>letters from relatives already there, and prepaid tickets they sent back</td></tr></table>`,qs:["Explain the difference between a push and a pull, using one example of each.","Why would a letter from a relative already living there be one of the strongest pulls of all?","Most Irish arrivals in the 1840s settled in eastern cities rather than buying farms. Looking at the chart, suggest why.","Pick one pull and explain how the geography or the transport systems of the country made it possible."],key:["A push drives a person away from where they are, such as a failed food crop in Ireland. A pull draws them toward somewhere else, such as cheap farmland. Most people move because of both at once. Partial: one of the two with an example is approaching. (HSS-5.8)","It came from someone they trusted who could say what the work paid and where to go, and sometimes it came with a prepaid ticket, which removed the biggest barrier of all. Partial: saying family matters with nothing said about trusted information or a prepaid ticket is approaching. (HSS-5.8)","They arrived with almost nothing after a famine, so buying land was out of reach. The pull column lists paid work in mills, on canals, and on railroads, which was in and around the eastern cities where their ships landed. Partial: naming the lack of money with nothing from the pull column is approaching. (HSS-5.8)","Any supported answer. Cheap farmland existed because the country had taken vast areas of land and surveyed it for sale, and reaching it was possible because canals, steamboats, and then railroads could carry a family and its goods inland cheaply. Partial: a pull named with no geography or transport behind it is approaching. (HSS-5.8)"]},{std:["HSS-5.9"],n:5,dur:90,dir:"Answer out loud. A map is fine to look at.",desc:"locating Midwest states and naming their capitals",html:()=>`<div class="figure">${F.icon("map",96)}${F.icon("globe",96)}</div>
     <p class="big">Questions about the middle of the country.</p>`,qs:["Name four states that touch one of the Great Lakes.","What is the capital of Illinois, and what is the capital of Ohio?","Which two states have Dakota in their names, and what are their capitals?","Which state is shaped like a mitten, and which large river forms the eastern border of Iowa?","How many states are there in all, and name three that touch the Mississippi River."],key:["Any four of Minnesota, Wisconsin, Illinois, Indiana, Michigan, Ohio, Pennsylvania, and New York. Partial: two or three of the four named is approaching. (HSS-5.9)","Springfield, Illinois and Columbus, Ohio. Note if the student names Chicago or Cleveland, which is the usual slip. Partial: one of the two capitals right is approaching. (HSS-5.9)","North Dakota, capital Bismarck, and South Dakota, capital Pierre. Partial: both states named with one capital missing is approaching. (HSS-5.9)","Michigan is the mitten. The Mississippi River forms Iowa's eastern border. Partial: one of the two answered is approaching. (HSS-5.9)","50 states. Any three of Minnesota, Wisconsin, Iowa, Illinois, Missouri, Kentucky, Tennessee, Arkansas, Mississippi, and Louisiana. Partial: the count right with two of the three states named is approaching. (HSS-5.9)"]}]}];const LEVELUPS={3:{id:"L3",title:"Level Up: Word Choice",std:["RL.6.4"],needs:["RL.5.4"],n:1,dir:"Answer out loud.",html:()=>`<p class="passage sm">${PASSAGE}</p><ol class="qlist"><li>The author wrote that the ice “rang like a struck bell.” Why is rang a stronger word there than made a noise? What does it make you feel about the moment?</li></ol>`,key:["Rang says the sound was clear and high, the way a solid thing sounds, so it tells you the ice was hard and ready to skate on. Made a noise tells you nothing about the ice. It makes the moment feel exciting and hopeful. (RL.6.4, impact of word choice on meaning and tone)"]},6:{id:"L6",title:"Level Up: Power Up",std:["6.EE.A.1"],needs:["5.OA.A.1"],n:3,dir:"Solve on your paper. Tell your teacher your answers.",html:()=>`<ol class="qlist"><li>4² = ?</li><li>3³ − 7 = ?</li><li>Write 5 × 5 × 5 with an exponent. Then find its value.</li></ol>`,key:["16 (6.EE.A.1)","20, because 3³ is 27 and 27 − 7 = 20 (6.EE.A.1)","5³, which is 125 (6.EE.A.1)"]},9:{id:"L9",title:"Level Up: Cocoa Box",std:["6.G.A.2"],needs:["5.MD.C.5"],n:2,dir:"Solve on your paper. Tell your teacher your answers.",html:()=>`<ol class="qlist"><li>A box of cocoa tins is 3 1/2 inches long, 2 inches wide, and 4 inches tall. What is its volume?</li><li>A sugar cube has edges that are 1/4 inch long. What is its volume?</li></ol>`,key:["28 cubic inches, from 3 1/2 × 2 × 4 (6.G.A.2)","1/64 cubic inch, from 1/4 × 1/4 × 1/4 (6.G.A.2)"]},10:{id:"L10",title:"Level Up: Four Quadrants",std:["6.NS.C.6"],needs:["5.G.A.1"],n:3,dir:"Look at the grid. Answer out loud.",html:()=>`<div class="figure">${grid4()}</div><ol class="qlist"><li>What are the coordinates of point M?</li><li>What are the coordinates of point N?</li><li>Point T is at (−1, −5). Which two ways do you move from the origin to get there?</li></ol>`,key:["(−4, 1) (6.NS.C.6)","(3, −2) (6.NS.C.6)","1 to the left, then 5 down (6.NS.C.6)"]},11:{id:"L11",title:"Level Up: Pronoun Fix",std:["L.6.1"],needs:["L.5.1"],n:3,dir:"Say each sentence out loud the correct way.",html:()=>`<ol class="qlist"><li>Fix it: “Her and me cleared the sidewalk.”</li><li>Fix it: “The neighbor paid Tomas and I.”</li><li>Finish it with a word that shows Rafi did it with no help: “Rafi ____ carried in all the firewood.”</li></ol>`,key:["She and I cleared the sidewalk. (L.6.1, subjective case)","Tomas and me (L.6.1, objective case)","himself (L.6.1, intensive pronoun)"]}};const SPLITS={thermometer:"ther·mom·e·ter",disappearance:"dis·ap·pear·ance",predictability:"pre·dict·a·bil·i·ty",uncomfortable:"un·com·fort·a·ble",immeasurable:"im·meas·ur·a·ble",invisibility:"in·vis·i·bil·i·ty",observation:"ob·ser·va·tion",electricity:"e·lec·tric·i·ty",unexpectedly:"un·ex·pect·ed·ly",disagreement:"dis·a·gree·ment",scrimbulation:"scrim·bu·la·tion",untrazzable:"un·traz·za·ble"};function tbl(rows,head){return`<div style="overflow-x:auto"><table class="chart">${head?`<tr>${head.map(h=>`<th>${h}</th>`).join("")}</tr>`:""}${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</table></div>`}function multChart(){let r=[];for(let i=0;i<=12;i++){const row=[];for(let j=0;j<=12;j++){row.push(i===0&&j===0?"×":i===0?`<b>${j}</b>`:j===0?`<b>${i}</b>`:i*j)}r.push(row)}return`<div style="overflow-x:auto"><table class="chart mult">${r.map((row,i)=>`<tr>${row.map((c,j)=>i===0||j===0?`<th>${c}</th>`:`<td>${c}</td>`).join("")}</tr>`).join("")}</table></div>`}function pvChart(){const head=["Thousands","Hundreds","Tens","Ones",".","Tenths","Hundredths","Thousandths"],vals=["1,000","100","10","1",".","0.1","0.01","0.001"],fr=["","","","",".","1/10","1/100","1/1000"];const cell=(c,i,tag,extra)=>{const dec=i>=4;const st=`padding:${tag==="th"?"8px 4px":"10px 4px"};text-align:center;${i===4?"width:20px;font-size:1.4rem;font-weight:700;":""}${dec&&i>4?"background:var(--sea-soft);":""}${extra||""}`;return`<${tag} style="${st}">${c}</${tag}>`};const row=(arr,tag,extra)=>`<tr>${arr.map((c,i)=>cell(c,i,tag,extra)).join("")}</tr>`;return`<div class="tool-scroll"><table class="chart" style="width:100%;font-size:.95rem">${row(head,"th","font-size:.74rem;white-space:nowrap;padding-left:1px;padding-right:1px;")}${row(vals,"td","font-weight:700;")}${row(fr,"td","font-size:.85rem;")}${row(["","","","",".","","",""],"td","height:54px;font-size:1.8rem;font-weight:700;")}</table></div><p class="small">The bottom row is for digits. Each place to the left is worth 10 times as much. Each place to the right is worth 1/10 as much. The last place, <b>thousandths</b>, is the third one after the point.</p>`}function strips(){const dens=[1,2,3,4,6,8,12],W=600,h=40;let s=`<svg viewBox="56 0 ${W+8} ${dens.length*(h+6)+4}" width="100%" style="max-width:640px" role="img" aria-label="Fraction strips">`;dens.forEach((d,r)=>{for(let k=0;k<d;k++){const x=60+k*W/d,y=2+r*(h+6);s+=`<rect x="${x}" y="${y}" width="${W/d}" height="${h}" fill="${["#F6D98A","#CFE7EC","#F9C9BE","#D6ECCF","#E6D6F2","#FCE2B5","#D9E4F5"][r]}" stroke="#1d3a44" stroke-width="1.5"/><text x="${x+W/d/2}" y="${y+h/2}" text-anchor="middle" dominant-baseline="central" font-size="${d>8?15:18}" fill="#15303A">${d===1?"1":"1/"+d}</text>`}});return s+"</svg>"}function coordMini(){return`<svg viewBox="0 -8 260 208" width="260" role="img" aria-label="Across then up"><line x1="30" y1="170" x2="240" y2="170" stroke="var(--ink)" stroke-width="3"/><line x1="30" y1="170" x2="30" y2="15" stroke="var(--ink)" stroke-width="3"/><text x="244" y="176" font-size="18" fill="var(--ink)">x</text><text x="24" y="12" font-size="18" fill="var(--ink)">y</text><text x="8" y="192" font-size="14" fill="var(--ink)">(0,0)</text><path d="M30 170 H150" stroke="var(--coral)" stroke-width="5" marker-end="url(#ah4)"/><path d="M150 170 V70" stroke="var(--sea)" stroke-width="5" marker-end="url(#ah4)"/><circle cx="150" cy="70" r="8" fill="var(--coral)"/><text x="44" y="160" font-size="15" fill="var(--ink)">1st: across</text><text x="158" y="125" font-size="15" fill="var(--ink)">2nd: up</text><defs><marker id="ah4" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0 L10 5 L0 10 z" fill="var(--ink)"/></marker></defs></svg>`}function clumpCue(){const star=(cx,cy,r)=>{let s="";for(let i=0;i<3;i++){const a=i*Math.PI/3,dx=(Math.cos(a)*r).toFixed(1),dy=(Math.sin(a)*r).toFixed(1);s+=`<path d="M${(cx-dx).toFixed(1)} ${(cy-dy).toFixed(1)} L${(cx- -dx).toFixed(1)} ${(cy- -dy).toFixed(1)}"/>`}return s};return`<svg viewBox="0 0 104 80" height="1.05em" style="vertical-align:-0.2em" role="img" aria-label="three ice crystals clumped together"><g stroke="var(--sea)" stroke-width="5" stroke-linecap="round" fill="none">${star(38,46,24)}${star(62,29,18)}${star(72,57,15)}</g></svg>`}const TOOLS={chunk:{name:"Show syllable chunks",std:["RF.5.3"],html:()=>`<p data-tpk="chunk" style="margin:0;font-size:1.15rem">Each word now shows with dots between its syllables. Close this tool to hide the chunks again.</p>`},prefix:{name:"Prefix, suffix, and root chart",std:["RF.5.3"],html:()=>tbl([["dis-, un-, in-, im-","not or the opposite of"],["pre-","before"],["-ment, -ance, -tion","act or result of"],["-able, -ible","can be"],["-ity","state of being"],["-ly","in that way"],["therm","heat"],["vis","see"],["dict","say"],["electr","electric"]],["Word part","Means"])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put it back together.</p>`},ruler:{name:"Reading ruler (one sentence at a time)",std:["RF.5.4"],html:()=>`<div data-tpk="ruler"><div class="row"><button class="chip" id="rulerBack">Back a sentence</button><button class="chip" id="rulerNext">Next sentence</button></div><p class="small">One sentence is lit up at a time. Sentence ${rulerIdx+1} of ${SENTS.length}. Close this tool to show the whole story again.</p></div>`,bind:(b,r)=>{b.querySelector("#rulerBack").onclick=()=>{rulerIdx=Math.max(0,rulerIdx-1);paintPsg();r()};b.querySelector("#rulerNext").onclick=()=>{rulerIdx=Math.min(SENTS.length-1,rulerIdx+1);paintPsg();r()}}},quote:{name:"Quote it sentence frames",std:["RL.5.1","RI.5.1"],html:()=>`<ul class="frames"><li>The text says, “______.”</li><li>I know ______ because the text says, “______.”</li><li>The words “______” show that ______.</li></ul><p class="chart-note">🔍 Find it → 👆 point to it → 🗣 read the exact words.</p>`},fig:{name:"Figurative language chart",std:["RL.5.4"],html:()=>tbl([["🔗 Simile","Compares two things using like or as","The lake was like glass."],["🎭 Metaphor","Says one thing IS another thing","The street was a river of snow."],["❓ What it means","Ask: what is really being compared? How does it feel?","A river of snow = deep and moving"]],["Type","What it does","Example"])},pv:{name:"Place value chart",std:["5.NBT.A.1","5.NBT.A.3"],html:pvChart},dec:{name:"Decimal anchor chart",std:["5.NBT.A.3"],html:()=>`<ul class="frames"><li><b>Read it:</b> say the whole number, say “and” at the decimal point, then read the digits and say the last place. 2.18 = two and eighteen hundredths.</li><li><b>Expanded form:</b> 7.52 = 7 × 1 + 5 × (1/10) + 2 × (1/100)</li><li><b>Compare:</b> line up the decimal points, add zeros so they are the same length, then compare place by place from the left. 0.70 vs 0.07</li></ul>`},ops:{name:"Order of operations chart",std:["5.OA.A.1"],html:()=>`<ol class="frames"><li>Work from the inside out: ( ) parentheses, then [ ] brackets, then { } braces.</li><li>Then × and ÷, left to right.</li><li>Then + and −, left to right.</li></ol><p class="chart-note">Example: 5 × [8 − (2 + 4)] → 5 × [8 − 6] → 5 × 2 = 10</p>`},mult:{name:"Multiplication chart",std:["5.NBT.A.1","5.OA.A.1","5.NF.A.1","5.NF.A.2","5.NF.B.3","5.NF.B.4","5.MD.C.3","5.MD.C.5","6.EE.A.1","6.G.A.2"],html:multChart},frac:{name:"Adding fractions steps",std:["5.NF.A.1","5.NF.A.2"],html:()=>`<ol class="frames"><li>Find a common denominator. List multiples: 5: 5, <b>10</b> &nbsp; 2: 2, 4, 6, 8, <b>10</b></li><li>Make equivalent fractions. Multiply top and bottom by the same number: 1/5 = 2/10, 1/2 = 5/10</li><li>Add or subtract the numerators. Keep the denominator: 2/10 + 5/10 = 7/10</li><li>Mixed numbers: add the wholes, add the fractions. Simplify or change an improper fraction to a mixed number.</li></ol><p class="chart-note">Check it: is the answer close to 0, 1/2, or 1? Does that make sense?</p>`},strips:{name:"Fraction strips",std:["5.NF.A.1","5.NF.A.2","5.NF.B.3","5.NF.B.4"],html:strips},fdiv:{name:"Fractions as division and multiplying chart",std:["5.NF.B.3","5.NF.B.4"],html:()=>`<ul class="frames"><li><b>A fraction is division:</b> 3/4 = 3 ÷ 4. 3 cookies shared by 4 people = 3/4 of a cookie each. 🍪🍪🍪 ÷ 👤👤👤👤</li><li><b>Improper to mixed:</b> 9/4 → 9 ÷ 4 = 2 R1 → 2 1/4</li><li><b>Multiply fractions:</b> top × top, bottom × bottom. 1/2 × 3/5 = 3/10</li><li><b>Whole number:</b> write it over 1. 2/3 × 5 = 2/3 × 5/1 = 10/3</li><li><b>“Of” means multiply:</b> 1/4 of 1/3 = 1/4 × 1/3</li></ul>`},vol:{name:"Volume anchor chart",std:["5.MD.C.3","5.MD.C.5"],html:()=>`<div class="figure" style="margin:0">${prism(2,2,1,28)}</div><ul class="frames"><li>Volume = how many unit cubes fill a solid. Units: cubic units, cubic cm (cm³), cubic inches.</li><li>V = length × width × height</li><li>V = B × h (B = area of the base)</li><li>Two boxes stuck together? Find each volume and add them.</li></ul>`},coord:{name:"Coordinate grid chart",std:["5.G.A.1"],html:()=>`<div class="figure" style="margin:0">${coordMini()}</div><ul class="frames"><li>(x, y): the first number goes <b>across</b> on the x-axis, the second goes <b>up</b> on the y-axis.</li><li>The origin is (0, 0), where the axes cross.</li><li>Walk before you climb.</li></ul>`},tense:{name:"Verb tense timeline",std:["L.5.1"],ok:st=>st.id===11,html:()=>tbl([["⏪ Past perfect","had + verb","I had eaten before the game."],["⏺ Present perfect","has/have + verb","I have eaten already."],["⏩ Future perfect","will have + verb","I will have eaten by 6."],["⚠ Tense shift","Keep the same time in a sentence","Yesterday I ran and jumped."]],["Tense","How to build it","Example"])},pos:{name:"Parts of speech chart",std:["L.5.1"],ok:st=>st.id===11,html:()=>tbl([["Conjunction","joins words or ideas","and, but, or, so, because"],["Correlative pair","conjunctions that work as a team","either/or, neither/nor, both/and, not only/but also"],["Preposition","shows where or when","in, on, under, across, through, after"],["Interjection","shows feeling","Oh! Hey! Yikes!"]],["Part of speech","Job","Examples"])},notes:{name:"Notes organizer",std:["W.5.8"],html:()=>tbl([["1.","",""],["2.","",""],["3.","",""]],["#","Note (my own words)","Text A or B"])+`<p class="chart-note">Sources: Text A: ______ &nbsp; Text B: ______</p>`},dict:{name:"Typing and voice typing help",std:["W.5.8","W.5.1","W.5.2","W.5.3"],html:()=>`<ul class="frames"><li>Type in a Google Doc or the meeting chat and send it to your teacher.</li><li>Google Docs voice typing: Tools, then Voice typing, then click the microphone.</li><li>Windows: press the Windows key + H.</li><li>Mac: Edit menu, then Start Dictation (or press the microphone or Fn key twice).</li><li>iPad or phone: tap the microphone on the keyboard.</li><li>Chromebook: Search + D (dictation must be on in accessibility settings).</li></ul>`},sumup:{name:"Summary picture cues and frame",std:["SL.5.2"],html:()=>`<p class="huge" style="font-size:2.6rem;margin:6px 0">${F.icon("cloud",42)} → ${F.icon("drop",42)} → ${F.icon("snowflake",42)} → ${clumpCue()} → ${F.icon("question",42)}</p><ul class="frames"><li>This is mostly about ______.</li><li>First, ______. Then, ______. Finally, ______.</li></ul>`},oreo:{name:"Opinion organizer and word bank",std:["SL.5.4","W.5.1"],html:()=>tbl([["O","Opinion","I think ______."],["R","Reason","One reason is ______."],["E","Example","For example, ______."],["O","Opinion again","That is why ______."]],["","Part","Starter"])+`<p class="chart-note">Linking words: for example, also, specifically, because of this, therefore, consequently</p>`},info:{name:"Informative organizer and word bank",std:["W.5.2"],html:()=>tbl([["Title","Name your topic"],["Intro","What is this about? Why does it matter?"],["Facts","Fact 1, Fact 2, Fact 3 (group ones that go together)"],["Closing","Sum it up in one sentence"]],["Part","What to write"])+`<p class="chart-note">Linking words: also, another, for example, especially, in contrast, as a result</p><p class="chart-note">Snow crystal words: cloud, dust, water vapor, freeze, crystal, six arms, clump &nbsp; Hare words: snowshoe hare, fur, daylight, sink in, bound</p>`},story:{name:"Story map and word bank",std:["W.5.3"],html:()=>tbl([["🎬 Beginning","Who is it about? Where are they? What were they planning to do?"],["⚡ Middle","What did the weather do? What happened next? What did people say?"],["🏁 End","How did it turn out? How did you feel?"]],["Part","Questions"])+`<p class="chart-note">Time words: first, at first, later, after that, suddenly, finally &nbsp; Senses: 👀 saw 👂 heard ✋ felt 👃 smelled</p><p class="chart-note">Dialogue: “We are not going anywhere today,” she said.</p>`}};const SUP_CAVEATS=[{t:"chunk",std:["RF.5.3"],msg:"With the syllable chunks showing, this stop shows the student can read words that are already split, not break long words apart alone."},{t:"ruler",std:["RF.5.4"],msg:"A timed read with the reading ruler is not a clean fluency baseline. The WCPM line in Notes says it was read with support."},{t:"fig",std:["RL.5.4"],msg:"The figurative language chart tells what a simile and a metaphor are, so count the simile or metaphor question as supported."},{t:"pv",std:["5.NBT.A.1"],msg:"The place value chart states the 10 times and 1/10 rule, which is what 5.NBT.A.1 checks. Count this stop as supported, not independent."},{t:"dec",std:["5.NBT.A.3"],msg:"The decimal chart shows how to read, expand, and compare decimals. Count this stop as supported, not independent."},{t:"ops",std:["5.OA.A.1"],msg:"The order of operations chart gives the order to work in. Count this stop as supported, not independent."},{t:"frac",std:["5.NF.A.1","5.NF.A.2"],msg:"The steps chart walks through finding a common denominator. Count the fraction answers as supported, not independent."},{t:"fdiv",std:["5.NF.B.3","5.NF.B.4"],msg:"This chart gives the rules for fractions as division and for multiplying fractions. Count this stop as supported, not independent."},{t:"vol",std:["5.MD.C.3","5.MD.C.5"],msg:"The volume chart tells what volume means and gives the formulas. Count those answers as supported."},{t:"coord",std:["5.G.A.1"],msg:"The coordinate chart shows the origin and the across-then-up rule. Count those questions as supported."},{t:"tense",std:["L.5.1"],msg:"The verb tense timeline shows how to build each tense. Count the tense items as supported."},{t:"pos",std:["L.5.1"],msg:"The parts of speech chart lists example words. Count the either/or item and the parts of speech item as supported."},{t:"sumup",std:["SL.5.2"],msg:"The picture cues give the order of the events, so count the order check as supported."},{t:"oreo",msg:"The organizer and word bank supply the structure, the linking words, and the closing. Count those checks as supported, not independent."},{t:"info",msg:"The organizer and word bank supply the structure, the linking words, and the topic words. Count those checks as supported, not independent."},{t:"story",msg:"The story map and word bank supply the structure, the time words, and a dialogue model. Count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.5.1","W.5.2","W.5.3","W.5.8"],msg:"If an adult wrote for the student, the ideas are the student’s but the spelling and punctuation are not. Pick Dictated in the box under the writing."}];const PASSAGE_STD=["RL.5.1","RL.5.4","RI.5.1","RI.5.9","RL.6.4"];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
